mapper.select:
SELECT adstrd_code
FROM dong_code
WHERE dong_code = #{dongCode}

SELECT * FROM ( SELECT hd.no, hi.apt_code, hi.apt_name, hi.dong_code, hi.build_year, hd.deal_year, hd.deal_month, hd.deal_day, hd.deal_amount, hi.lat, hi.lng FROM house_deal hd JOIN house_info hi ON hd.apt_code = hi.apt_code ORDER BY hd.no DESC LIMIT 18446744073709551615 ) hh
AND dong_code = #{dongCode}
AND SUBSTRING(dong_code, 1, 5) = SUBSTRING(#{gugunCode}, 1, 5)
AND SUBSTRING(dong_code, 1, 2) = SUBSTRING(#{sidoCode}, 1, 2)
AND apt_name LIKE CONCAT('%', #{keyword}, '%')
GROUP BY apt_code LIMIT #{limit} OFFSET #{offset}

SELECT count(*)
FROM house_deal
WHERE apt_code = #{aptCode}

SELECT * FROM ( SELECT hd.no, hi.apt_code, hi.apt_name, hi.dong_code, hi.build_year, hd.deal_year, hd.deal_month, hd.deal_day, hd.deal_amount, hi.lat, hi.lng FROM house_deal hd JOIN house_info hi ON hd.apt_code = hi.apt_code WHERE hd.apt_code IN
#{aptCode}
ORDER BY hd.no DESC LIMIT 18446744073709551615 ) hh GROUP BY apt_code

SELECT sido_name, gugun_name, dong_name, dong_code FROM base_address WHERE dong_code IN
#{dongCode}
ORDER BY dong_name
